Formula:
OR(
    AND(
        ISPICKVAL(Lead_Drop_Reason__c, "Others"),
        ISBLANK(Please_Specify__c)
    ),
    AND(
        OR(
            ISPICKVAL(Status, "Dropped"),
            ISPICKVAL(Status, "Dropped by Central desk")
        ),
        ISBLANK(TEXT(Lead_Drop_Reason__c))
    )
)

OR(
    AND(
        NOT(IsVRBypassed__c),
        ISBLANK(PostalCode)
    ),
    AND(
        NOT(ISBLANK(PostalCode)),
        NOT(REGEX(PostalCode, "^[0-9]{6}$"))
    )
)
